const add = (a, b) => a + b;
const ops = { plus: add, minus: (a, b) => a - b };
const again = ops.plus;

function run(op, a, b) {
  return op(a, b);
}

console.log(run(again, 2, 3));
console.log(run(ops.minus, 2, 3));
console.log(again === add);
console.log(typeof run);
console.log(typeof run(add, 1, 1));
